insert into public.news_articles (slug, title, category, summary, body, image_path, status, published_at)
values
  ('free-online-ami-seminar-regulation-the-law-and-our-asbestos-legacy', 'Free Online AMI Seminar: Regulation, the Law and Our Asbestos Legacy', 'Events', 'The Asbestos Management Institute is holding a free online seminar on Thursday 26 November 2026.', '<p>The Asbestos Management Institute is holding a free online seminar on Thursday 26 November 2026.</p><p>Three speakers will cover where the regulator is heading, the latest developments in corporate manslaughter and asbestos prosecutions, and the question the industry keeps returning to: should Great Britain manage its asbestos legacy or remove it.</p><p>Join the Asbestos Management Institute (AMI) for a free online seminar:</p><p><strong>Date:</strong> Thursday 26 November 2026<br> <strong>Time:</strong> 10:30am-12:00pm<br> <strong>Location:</strong> Online via Zoom<br> <strong>Cost:</strong> Free to attend and open to all</p><p>Register <a href="https://us02web.zoom.us/meeting/register/YXUVAGcrRu6WqNQmhkNgvg#/registration">here</a></p><p><strong>Speakers and Topics</strong></p><p><strong>1. Sam Lord (HSE)</strong>: <strong>HSE update: the CAR 2012 consultation response and leak testing guidance</strong><em>.</em></p><p>Her HSE update will cover HSE''s response to the consultation on legislative and guidance proposals for the Control of Asbestos Regulations 2012, and the new Asbestos Network TWG Appendix: Guidance for Licensed Asbestos Removal Contractors on Leak Testing Risk Assessment.</p><p><strong>2. George Emery (Kennedys Law LLP)</strong>: <strong>Corporate manslaughter and asbestos prosecutions: what we are seeing</strong><em>.</em></p><p>He acts for and advises companies and individuals subject to regulatory investigations and prosecutions brought by the Health and Safety Executive, the police, local authorities, the Environment Agency and fire services, often in complex and high-profile health and safety and environmental cases<em>. </em>His presentation is in two parts. The first looks at the developments Kennedys is seeing in corporate manslaughter. The second turns to prosecutions specific to asbestos.</p><p><strong>3. Professor John Cherrie (Heriot-Watt University)</strong>: <strong>Our asbestos legacy: manage or remove?</strong></p><p>He is the Emeritus Professor of Human Health at Heriot-Watt University and a retired Research Director at the Institute of Occupational Medicine in Edinburgh.His presentation asks how Great Britain should deal with the asbestos still in its buildings, and whether the answer is to manage it in place or to remove it</p><p>The event is ideal for professionals involved in asbestos management, removal, surveying, consultancy, testing, and duty holders responsible for buildings containing asbestos. Attendance is free, and the seminar is open to everyone, whether or not you are a member of AMI.</p><p>Register <a href="https://us02web.zoom.us/meeting/register/YXUVAGcrRu6WqNQmhkNgvg#/registration">here</a></p>', '/assets/news-free-online-ami-seminar-regulation-the-law-and-our-asbesto.webp', 'published', timestamp '2026-10-23 12:00' at time zone 'Europe/London'),
  ('expert-led-asbestos-management-seminar-successfully-brings-together-in', 'Expert-Led Asbestos Management Seminar Successfully Brings Together Industry Professionals', 'Events', 'The Asbestos Management Institute hosted a successful virtual seminar on asbestos management on November 27th, 2025, bringing together industry-leading experts and over 120 professionals for an informative two-hour session via Zoom.', '<p>The Asbestos Management Institute hosted a successful virtual seminar on asbestos management on November 27th, 2025, bringing together industry-leading experts and over 120 professionals for an informative two-hour session via Zoom. The event, which was open to both members and non-members, attracted asbestos professionals keen to stay updated on the latest developments in the field.</p><p><strong>Key Presentations and Insights</strong></p><p>The seminar featured four speakers who delivered presentations on topics affecting the asbestos management industry:</p><p><strong>Stefan Bristow</strong> from The Stationery Office (HSE Publishers) opened the session with an exploration of the Safety Climate Tool, discussing how this assessment framework evaluates workplace safety culture and supports organisational development initiatives.</p><p><strong>Amanda James</strong> from the Health &amp; Safety Executive (HSE) provided valuable guidance on the licence application assessment process. Her presentation highlighted common errors identified during application assessments and offered practical advice to help licence applicants submit stronger, more complete applications.</p><p><strong>Trisha Parker</strong> from Investors in People (IIP) discussed the internationally recognised accreditation for people management and employee wellbeing, explaining how organisations in the asbestos sector can benefit from this framework.</p><p><strong>Moya Woolley</strong> from the Health &amp; Safety Executive (HSE) concluded the seminar by discussing the ongoing consultation on legislative and guidance proposals for the Control of Asbestos Regulations 2012.</p><p>The virtual format enabled professionals from across the industry to participate and engage with the expert speakers, reinforcing the Asbestos Management Institute''s commitment to providing accessible, high-quality professional development opportunities for the asbestos management community.</p><p>Thank you once again to all who attended and contributed to making this event a great success!</p><p>View presentation videos <a href="/videos"><strong>here </strong></a></p>', '/assets/news-expert-led-asbestos-management-seminar-successfully-brings.webp', 'published', timestamp '2025-12-02 12:00' at time zone 'Europe/London'),
  ('free-expert-led-asbestos-management-seminar-for-asbestos-professionals', 'Free Expert-Led Asbestos Management Seminar for Asbestos Professionals', 'Events', 'Join us for an insightful virtual seminar on asbestos management, featuring industry-leading experts. Open to both members and non-members of the Asbestos Management Institute.', '<p> Join us for an insightful virtual seminar on asbestos management, featuring industry-leading experts. Open to both members and non-members of the Asbestos Management Institute.</p><p><strong>Date: November 27th, 2025 Time: 10:30 AM Duration: Approximately 2 hours Platform: Zoom</strong><br> </p><p><u><strong>Featured Speakers and Topics</strong></u></p><ol>
<li><strong>Stefan Bristow from The Stationery Office (HSE Publishers)</strong> speaking on the Safety Climate Tool, which assesses workplace safety culture to support organisational development.</li>
<li><strong>Amanda James from the Health &amp; Safety Executive (HSE) </strong>speaking on the licence application assessment process, common errors found during assessment, and how licence applicants can provide better applications.</li>
<li><strong>Trisha Parker from Investors in People (IIP) </strong>speaking on the internationally recognised accreditation for people management and employee wellbeing.</li>
<li><strong>Christopher Carpenter from 3M Personal Safety Division</strong> speaking on Personal Protective Equipment (PPE) and Respiratory Protective Equipment (RPE) in the asbestos management industry.</li>
<li><strong>Moya Woolley from the Health &amp; Safety Executive (HSE)</strong> speaking on the consultation on legislative and guidance proposals for the Control of Asbestos Regulations 2012.</li>
</ol>The conference will feature presentations by industry professionals that will be of interest to anyone involved in asbestos management. The seminar will last approximately 2 hours.<p><strong>Registration:</strong> Open to all. Please complete the <a href="https://us02web.zoom.us/meeting/register/DPM-h45KR0OwVQQrDe4SVg#/registration">registration form</a> to secure your spot.</p>', '/assets/news-free-expert-led-asbestos-management-seminar-for-asbestos-p.webp', 'published', timestamp '2025-10-20 12:00' at time zone 'Europe/London'),
  ('asbestos-management-institute-celebrates-milestone-growth-with-100-mem', 'Asbestos Management Institute Celebrates Milestone Growth with 100 Members', 'Institute', 'The Asbestos Management Institute (AMI) proudly announces a significant milestone this month, as it welcomes its 100th member.', '<p>The Asbestos Management Institute (AMI) proudly announces a significant milestone this month, as it welcomes its 100th member. This achievement highlights the increasing importance of professional asbestos management and AMI''s role in promoting safe and effective practices within the industry.</p><p><strong>About the Asbestos Management Institute</strong></p><p>AMI serves as a professional body dedicated to recognising and promoting best practices in asbestos management. Founded with the vision of creating a collaborative platform for industry professionals.</p><p>By fostering a collaborative environment, AMI empowers its members to influence and shape the future of the asbestos management landscape. The institute brings together contractors, consultants, training providers, and other stakeholders committed to maintaining the highest standards in asbestos management.</p><p><strong>Valuable Member Benefits</strong></p><p>Individuals joining AMI benefit from numerous advantages that support their professional growth and operational excellence:</p><ul>
<li>Recognition as a committed asbestos management professional adhering to best practices</li>
<li>Access to a network of industry leaders and experts</li>
<li>Opportunities for knowledge sharing and professional development</li>
<li>A collective voice in shaping industry standards</li>
</ul><p>The diverse membership includes asbestos removal contractors, consultants, training providers, and equipment manufacturers, creating a comprehensive ecosystem of expertise.</p><p><strong>Looking Forward</strong></p><p>The Asbestos Management Institute''s growth to 100 members signifies a collective commitment to excellence in asbestos management. By joining AMI, individuals not only enhance their professional connections but also become part of a larger movement advocating for safety and innovation in the industry.</p><p>Together, AMI and its members are dedicated to advancing the standards of asbestos management for a safer future through professional expertise, innovation, and collaboration.</p>', '/assets/news-asbestos-management-institute-celebrates-milestone-growth.webp', 'published', timestamp '2025-05-06 12:00' at time zone 'Europe/London'),
  ('amis-3rd-annual-general-meeting-recap', 'AMI''s 3rd Annual General Meeting Recap', 'Events', 'On April 10th, 2025, we hosted the 3rd Annual General Meeting (AGM) for the Asbestos Management Institute (AMI) via Zoom.', '<p>On April 10th, 2025, we hosted the 3rd Annual General Meeting (AGM) for the Asbestos Management Institute (AMI) via Zoom. It was an incredibly engaging and informative session, bringing together professionals from the asbestos management field and beyond.</p><p>The presentation opened with Edward Strong, the newly appointed President of AMI, who will now serve as our AMI representative on the Asbestos Network Technical Working Group (ANTWG), ensuring our voices are heard at a national level.</p><p>Over the past 12 months, AMI has experienced an increase in membership and achieved several important milestones. We''ve joined forces with the Asbestos Information Certificate (CIC) initiatives and strengthened our collaboration with ATAC. This partnership has led to the launch of new AMI-CPQ memberships for individuals holding RSPH Level 4 qualifications, as well as the introduction of the new ''AAMI'' post-nominal designation for those with RSPH Level 3 qualifications.</p><p>Looking ahead, there are several initiatives on the horizon, including prostate cancer testing and complimentary HR services through our partnership with Croner.</p><p>A special thank you to our speakers:</p><p>🔹 <strong>Lyndsey Baldwin</strong> (HSE, Asbestos Policy) shared key updates on evolving HSE policies and what they mean for the future of our industry.</p><p>🔹 <strong>Phil Ormesher</strong> of the Prostate Cancer Support Group brought a vital health-focused message. He introduced a new health testing portal now available to AMI members, aimed at promoting early detection and ongoing well-being.</p><p>🔹 <strong>Martin Saunders</strong> (HSE, Senior Scientist) walked us through the latest research on asbestos removal controls, emphasising the importance of safety and compliance.<br><br> 🔹 <strong>John Richards</strong> (Asbestos Information CIC) offered practical strategies and actionable insights on improving asbestos management practices.</p><p>The webinar format proved effective, with over 160 industry professionals in attendance. The Q&amp;A sessions following each presentation generated thoughtful discussion and knowledge sharing. Participants actively engaged with speakers, raising important questions about asbestos regulatory compliance and technical challenges.</p><ul>
<li>Webinar video links can be found<a href="/videos"> <strong>here</strong></a></li>
<li>Link for prostate cancer detection testing available <a href="https://ami.mypsatests.org.uk/">here </a></li>
</ul>', '/assets/news-amis-3rd-annual-general-meeting-recap.webp', 'published', timestamp '2025-04-11 12:00' at time zone 'Europe/London'),
  ('parliamentary-launch-of-asbestos-information-cics-national-strategy-re', 'Parliamentary Launch of Asbestos Information CIC''s National Strategy Report', 'Industry', 'Earlier this morning, during Global Asbestos Awareness Week, Asbestos Information CIC presented its comprehensive proposal for a national asbestos strategy at a parliamentary launch event in Portcullis House.', '<p>Earlier this morning, during Global Asbestos Awareness Week, Asbestos Information CIC presented its comprehensive proposal for a national asbestos strategy at a parliamentary launch event in Portcullis House. Steve Sadley, CEO of the Asbestos Management Institute, attended the event as industry professionals gathered to address one of the UK''s most pressing public health challenges.</p><p>The report directly addressed the two core recommendations from the 2022 Department for Work and Pensions inquiry into the Health and Safety Executive''s management of asbestos: developing a national database of asbestos in buildings and creating a strategy for its phased removal.</p><p><strong>A Data-Driven Approach to an Ongoing Challenge</strong></p><p>Despite the UK''s ban on asbestos use since 1999, the country continues to have one of the highest rates of mesothelioma deaths globally, with over 5,000 asbestos-related fatalities annually, accounting for 40% of the UK''s occupational cancer cases. The report revealed alarming statistics, including data showing that almost 3 million asbestos items were identified in the dataset, with the highest risk group (E-G) accounting for nearly 26% of all identified asbestos. At current removal rates, addressing this issue could take up to 100 years.</p><p>Even more concerning, the report found that 71% of recorded asbestos items had some damage, and almost 30% of high-risk items suffered moderate or significant damage, suggesting that asbestos management was ineffective.</p><p>Central to the proposal is the introduction of an Asbestos Information Certificate (AIC), modelled after Energy Performance Certificates. This innovative approach would provide clear, accessible information about asbestos risk in buildings while forming the foundation of a comprehensive national database.</p><p><strong>A Collaborative Industry Initiative</strong></p><p>The strength of this initiative lies in its collaborative approach. Today''s launch featured representation from across the asbestos sector, including ARCA (Asbestos Removal Contractors Association), ATAC (Asbestos Testing and Consultancy Association), and AMI (Asbestos Management Institute), alongside representatives from UKAS-accredited inspection bodies—all founding members of Asbestos Information CIC. This comprehensive industry participation reflects the broad professional commitment to improving asbestos management standards nationwide. Industry professionals have seen first hand how this coordinated approach could transform asbestos management across the UK.</p><p>The report''s analysis of over 7 million lines of data from nearly 400,000 properties represents the most extensive dataset on asbestos ever compiled in the UK. This unprecedented collaboration demonstrates the industry''s commitment to prioritising public health.</p><p><strong>Strategic Implementation</strong></p><p>The report outlined a five-step approach to building a national asbestos strategy:</p><ol>
<li>Identifying properties likely to contain asbestos</li>
<li>Rationalising data collection and terminology</li>
<li>Presenting data through the Asbestos Information Certificate</li>
<li>Implementing the AIC across sectors, beginning with education</li>
<li>Planning for future phased removal, prioritising buildings housing vulnerable populations</li>
</ol><p>With an estimated £50 billion maintenance backlog across UK public buildings, increasing by £800 million per annum, the event emphasised the critical importance of integrating asbestos management into broader infrastructure and Net Zero planning.</p><p>This morning''s parliamentary launch represented a vital step toward addressing this ongoing public health issue through collaborative, data-driven solutions. Attendees were pleased to see the engagement from policymakers, industry professionals, and stakeholders at the event, which demonstrated strong support for this essential initiative.</p><p><a href="https://asbestosinformation.org.uk/report-2025/#p=1"><u>View report here </u></a></p>', '/assets/news-parliamentary-launch-of-asbestos-information-cics-national.webp', 'published', timestamp '2025-04-03 12:00' at time zone 'Europe/London'),
  ('atac-and-ami-launch-joint-membership-initiative-to-enhance-asbestos-pr', 'ATaC and AMI Launch Joint Membership Initiative to Enhance Asbestos Professional Recognition', 'Institute', 'In a significant move for the asbestos management industry, the Asbestos Testing and Consultancy Association (ATaC) and the Asbestos Management Institute (AMI) have announced a strategic partnership aimed at elevating professional…', '<p>In a significant move for the asbestos management industry, the Asbestos Testing and Consultancy Association (ATaC) and the Asbestos Management Institute (AMI) have announced a strategic partnership aimed at elevating professional standards and recognition within the sector.</p><p>The collaboration introduces a groundbreaking membership initiative that provides qualified professionals with enhanced credentials and industry standing. Under the new program, individuals who successfully complete the Royal Society for Public Health (RSPH) Level 3 and Level 4 qualifications will receive complimentary yearly AMI memberships and prestigious post-nominal designations.</p><p><strong>Premium Recognition for RSPH Level 4 Qualification Holders</strong></p><p>Professionals who have earned the RSPH Level 4 Certificate in Asbestos Laboratory and Project Management will be granted a one-year complimentary AMI Competent Professional Qualification (CPQ) Membership. This membership tier offers significant networking opportunities, access to industry insights, and the ability to stay current with evolving trends. Qualified members can proudly display the "AMI-CPQ" credential after their names and enjoy full voting rights within the organisation.</p><p><strong>Enhanced Status for RSPH Level 3 Qualification Holders</strong></p><p>Those who complete RSPH Level 3 qualifications in specialised areas such as Analysis, Surveying, Dutyholder or Bulk Identification will be granted AMI Associate Grade membership. This recognition allows professionals to use the "AAMI" post-nominal, acknowledging their expertise and dedication to professional excellence.</p><p>The initiative encompasses various RSPH Level 3 certification paths, including:</p><ul>
<li>RSPH Level 3 Surveying</li>
<li>RSPH Level 3 Air Monitoring</li>
<li>RSPH Level 3 Bulk Analysis</li>
<li>RSPH Level 3 Dutyholder</li>
</ul><p><strong>Streamlined Implementation Process</strong></p><p>ATaC has committed to processing memberships retroactively and will send notification letters to all eligible professionals. This ensures that currently qualified individuals can immediately benefit from the new program without administrative barriers.</p><p><strong>Setting New Industry Standards</strong></p><p>Steve Sadley, Honorary Fellow of AMI, emphasised the significance of this partnership: "This collaborative initiative represents a significant step forward for our industry. By providing clear pathways for professional development and recognition, ATaC and AMI are setting a new standard for excellence in asbestos management and testing."</p><p>Industry experts anticipate that this joint initiative will contribute to higher professional standards and improved asbestos management practices across the sector.</p><p>For additional information regarding membership eligibility and benefits, interested parties are encouraged to contact ATaC or AMI directly.</p>', null, 'published', timestamp '2025-03-25 12:00' at time zone 'Europe/London'),
  ('ami-3rd-annual-general-meeting', 'AMI 3rd Annual General Meeting', 'Events', 'The 3rd Asbestos Management Institute (AMI) Annual General Meeting (AGM) will be held on April 10th, 2025. As with last year, the meeting is open to both members and non-members alike and is free of charge.', '<p>The 3rd Asbestos Management Institute (AMI) Annual General Meeting (AGM) will be held on April 10th, 2025. As with last year, the meeting is open to both members and non-members alike and is free of charge.</p><p>The speaker line-up is currently being finalised, but we can confirm that the following speakers have agreed to participate:</p><ul>
<li><strong>Martin Saunders, HSE Senior Scientist, Health</strong> – Exposure Control Group, who will summarise the recent reports into the use of control measures during licensed asbestos removal and the effectiveness of 4-Stage Clearance after Licensed Removal.</li>
<li><strong>Lyndsey Baldwin, HSE, Asbestos Policy, Engagement and Policy Division</strong>, who will provide an update on current HSE policy in relation to the formal consultation of the DWP committee recommendations.</li>
</ul><p>The meeting will be conducted via Zoom Video Conferencing and is free to attend, CPD certificates will be issued to attendees.</p><p>The agenda is available here and you can register to attend<a href="https://us02web.zoom.us/meeting/register/7fXKAGIIRYyw7cJghYr20w#/registration"> here.</a></p>', '/assets/news-ami-3rd-annual-general-meeting.webp', 'published', timestamp '2025-02-27 12:00' at time zone 'Europe/London'),
  ('asbestos-management-seminar-recap-a-day-of-critical-insights-and-exper', 'Asbestos Management Seminar Recap: A Day of Critical Insights and Expert Knowledge', 'Events', 'The Asbestos Management Seminar, which took place on 5th December 2024, successfully brought together over 185 participants for an insightful and informative session.', '<p>The Asbestos Management Seminar, which took place on 5th December 2024, successfully brought together over 185 participants for an insightful and informative session. The event featured leading experts in the field of asbestos management, offering critical insights into best practices, and emerging technologies.</p><p>We would like to extend a heartfelt thank you to all our distinguished speakers:</p><ul>
<li><strong>Samantha Lord</strong> from the Health &amp; Safety Executive (HSE), who provided valuable information on Asbestos Waste Storage and Movement on Site, as well as the Site Supervisor Visual Inspection and Handover Form.</li>
<li><strong>Charlotte Burton</strong> from Asbestos Information Certificate CIC, who shared her expertise on Data-Driven Initiatives for Simplifying Asbestos Surveys and Effective Asbestos Management Strategies.</li>
<li><strong>Nick Garland</strong> from Assure360, discussed Gel Cutting as a Safer Alternative to Wrap and Cut methods.</li>
<li><strong>Stephen Freeland</strong> from the Environmental Services Association (ESA), who discussed Minimum Standards for Presenting Bonded Asbestos to Disposal Sites.</li>
<li><strong>Paul Manning</strong> from the British Safety Industry Federation (BSIF), delivered a presentation on The Truth About Substandard PPE in the UK.</li>
</ul><p>The event successfully brought together industry professionals to share knowledge, discuss current challenges, and explore innovative solutions in asbestos management</p><p>Thank you once again to all who attended and contributed to making this event a great success!</p><p>View presentation videos <a href="/videos">here </a></p>', '/assets/news-asbestos-management-seminar-recap-a-day-of-critical-insigh.webp', 'published', timestamp '2024-12-09 12:00' at time zone 'Europe/London'),
  ('asbestos-management-seminar-expert-insights-and-best-practices', 'Asbestos Management Seminar: Expert Insights and Best Practices', 'Events', 'Join us for an insightful virtual seminar on asbestos management, featuring industry-leading experts. Open to both members and non-members of the Asbestos Management Institute.', '<p><strong>Join us for an insightful virtual seminar on asbestos management, featuring industry-leading experts. Open to both members and non-members of the Asbestos Management Institute.</strong></p><p><strong>Date:</strong> December 5th, 2024 <strong>Time:</strong> 10:30 AM <strong>Duration:</strong> Approximately 2 hours <strong>Platform:</strong> Zoom</p><p><strong>Featured Speakers and Topics:</strong></p><ol>
<li><strong>Sam Lord</strong> (Health and Safety Executive)
<ul>
<li>Asbestos Waste Storage and Movement on Site</li>
<li>Site Supervisor Visual Inspection and Handover Form</li>
</ul>
</li>
<li><strong>John Richards</strong> (Asbestos Information Certificate CIC)
<ul>
<li>A Data-Driven Initiative to Simplify Asbestos Surveys</li>
<li>Identifying Steps for More Effective Asbestos Management</li>
</ul>
</li>
<li><strong>Nick Garland</strong> (Assure360)
